<template>
    <div>
        <ion-page>
            <ion-header>
                <ion-toolbar>
                    <ion-title style="font-size: 25px; font-weight: 600">{{
                        showConfirm ? "Confirm Rejection" : "Reject Order"
                    }}</ion-title>
                    <ion-buttons slot="end">
                        <ion-button :strong="true" @click="handleDialog">
                            <ion-icon size="large" :icon="close"></ion-icon>
                        </ion-button>
                    </ion-buttons>
                </ion-toolbar>
            </ion-header>
            <ion-content>
                <!-- Step 1: reason -->
                <ion-list v-if="!showConfirm">
                    <ion-item>
                        <ion-label style="font-size: 20px; font-weight: 600">Test Types</ion-label>
                        <ion-label slot="end" style="font-size: 18px;">{{ details?.tests?.map((test) =>
                            test.test_type).join(", ") }}</ion-label>
                    </ion-item>
                    <ion-item>
                        <ion-label style="font-size: 20px; font-weight: 600">Specimen</ion-label>
                        <ion-label slot="end" style="font-size: 18px;">{{ details?.tests ? details?.tests[0]?.specimen :
                            '' }}</ion-label>
                    </ion-item>
                    <ion-item>
                        <ion-label style="font-size: 20px; font-weight: 600">Patient Name</ion-label>
                        <ion-label slot="end" style="font-size: 18px;">
                            {{ details ?
                                `${details?.first_name} ${details?.middle_name ? details?.middle_name :
                                    ''} ${details?.last_name}` :
                                ''
                            }}
                        </ion-label>

                    </ion-item>
                    <ion-item>
                        <ion-label style="font-size: 20px; font-weight: 600">Tracking Number</ion-label>
                        <ion-label slot="end" style="font-size: 18px;">{{ details?.tracking_number }}</ion-label>
                    </ion-item>
                    <ion-item>
                        <ion-label style="font-size: 20px; font-weight: 600">Accession Number</ion-label>
                        <ion-label slot="end" style="font-size: 18px;">{{ details?.accession_number }}</ion-label>
                    </ion-item>
                    <ion-item>
                        <ion-label style="font-size: 20px; font-weight: 600">Person Talked To:
                        </ion-label>
                        <ion-input v-model="personTalkedTo" required placeholder="Enter full name"
                            @ion-focus="enterInput('person')" style="font-size: 18px;" />
                    </ion-item>

                    <ion-item>
                        <ion-label style="font-size: 20px; font-weight: 600">Rejection Reason:
                        </ion-label>
                        <ion-select required v-model="selectedStatusReason">
                            <ion-select-option v-for="reason in statusReasons" v-bind:key="reason.description"
                                :value="reason.description" style="font-size: 18px;">{{ reason.description
                                }}</ion-select-option>
                            <ion-select-option :value="OTHER_OPTION" style="font-size: 18px;">Other (enter
                                manually)</ion-select-option>
                        </ion-select>
                    </ion-item>

                    <ion-item v-if="selectedStatusReason === OTHER_OPTION">
                        <ion-label position="stacked" style="font-size: 20px; font-weight: 600">Specify
                            Reason:</ion-label>
                        <ion-textarea v-model="otherReason" :auto-grow="true" required
                            placeholder="Type the reason in full" @ion-focus="enterInput('reason')"
                            style="font-size: 18px;" />
                    </ion-item>

                    <ion-item v-if="selectedStatusReason === OTHER_OPTION && reasonSuggestions.length" lines="none">
                        <div>
                            <p style="font-size: 15px; color: var(--ion-color-medium); margin: 4px 0;">
                                Similar existing reasons &mdash; tap to use one:
                            </p>
                            <ion-chip v-for="suggestion in reasonSuggestions" :key="suggestion" color="success" outline
                                @click="applySuggestion(suggestion)">
                                <ion-label>{{ suggestion }}</ion-label>
                            </ion-chip>
                        </div>
                    </ion-item>
                </ion-list>

                <!-- Step 2: choose what is being rejected -->
                <ion-list v-else>
                    <ion-item lines="none">
                        <ion-label class="ion-text-wrap" style="font-size: 16px; color: var(--ion-color-medium);">
                            Rejecting <strong>every</strong> test also rejects the specimen (the whole order).
                            Rejecting <strong>some</strong> tests leaves the specimen usable for the rest &mdash;
                            the order status is not changed.
                        </ion-label>
                    </ion-item>

                    <ion-item>
                        <ion-checkbox slot="start" v-model="rejectAllExplicit"></ion-checkbox>
                        <ion-label style="font-size: 18px; font-weight: 700;">
                            Reject the ENTIRE order (specimen + every test)
                        </ion-label>
                    </ion-item>

                    <ion-item v-for="t in details?.tests || []" v-bind:key="t.id">
                        <ion-checkbox slot="start" :disabled="rejectAllExplicit"
                            :checked="rejectAllExplicit || selectedTestIds.includes(t.id)"
                            @ion-change="toggleTest(t.id, $event)"></ion-checkbox>
                        <ion-label style="font-size: 18px;">{{ t.test_type }}</ion-label>
                        <ion-note slot="end" style="font-size: 15px;">{{ formatStatus(t.test_status) }}</ion-note>
                    </ion-item>

                    <ion-item lines="none" v-if="!canConfirm">
                        <ion-label style="font-size: 15px; color: var(--ion-color-danger);">
                            Select at least one test, or choose "Reject the ENTIRE order".
                        </ion-label>
                    </ion-item>
                </ion-list>

                <div class="keyboard" v-show="showKeyboard">
                    <SimpleKeyboard @onChange="onChange" @onKeyPress="onKeyPress"
                        :input="focusedField === 'reason' ? otherReason : personTalkedTo"
                        :inputName="focusedField === 'reason' ? otherReason : personTalkedTo" />
                </div>
            </ion-content>

            <ion-footer>
                <ion-toolbar color="light" style="padding: 5px">
                    <template v-if="!showConfirm">
                        <ion-button slot="start" size="large" color="danger" @click="cancelReject">
                            Cancel
                        </ion-button>
                        <ion-button slot="end" :disabled="!isset" size="large" color="success" @click="goToConfirm">
                            Continue
                        </ion-button>
                    </template>
                    <template v-else>
                        <ion-button slot="start" size="large" color="medium" @click="showConfirm = false">
                            Back
                        </ion-button>
                        <ion-button slot="end" :disabled="!canConfirm" size="large" color="success" @click="submitForm">
                            Confirm Rejection
                        </ion-button>
                    </template>
                </ion-toolbar></ion-footer>
        </ion-page>
    </div>
</template>

<script setup lang="ts">
import { Client } from "@/composables/client";
import { computed, onMounted, ref } from "vue";
import { useRoute, useRouter } from "vue-router";
import { close } from "ionicons/icons";
import { alertConfirmation, toastSuccess } from "@/utils/Alerts";
import {
    IonButtons,
    IonButton,
    IonIcon,
    IonHeader,
    IonContent,
    IonToolbar,
    IonTitle,
    IonItem,
    IonLabel,
    IonFooter,
    IonList,
    IonPage,
    IonSelect,
    IonSelectOption,
    IonInput,
    IonTextarea,
    IonChip,
    IonCheckbox,
    IonNote,
} from "@ionic/vue";
import SimpleKeyboard from "@/components/Keyboard/SimpleKeyBoard.vue";

// Sentinel option that reveals the free-text reason field.
const OTHER_OPTION = "Other";

type LabLocation = {
    id: number;
    name: string;
};

type Test = {
    id: number;
    specimen_id: number;
    specimen: string;
    test_type: string;
    test_type_short_name: string;
    test_status: string;
};

type Order = {
    source: string;
    client_id: number;
    first_name: string;
    middle_name: string;
    last_name: string;
    sex: "M" | "F";
    date_of_birth: string;
    birth_date_estimated: boolean;
    uuid: string;
    created_at: string;
    lab_location: LabLocation;
    physical_address: string;
    npid: string;
    order_id: number;
    accession_number: string;
    tracking_number: string;
    requested_by: string;
    collected_by: string;
    registered_by: string;
    priority: string;
    sending_facility: string;
    destination_facility: string;
    date_created: string;
    order_status_id: number;
    order_status_name: string;
    tests: Test[];
};


const route = useRoute();
const router = useRouter();
const client = Client();
const details = ref<Order>();
const personTalkedTo = ref<string>("");
const statusReasons = ref<Array<{ id: number; description: string }>>([]);
const selectedStatusReason = ref<string>("");
const otherReason = ref<string>("");
const focusedField = ref<"person" | "reason">("person");

const showConfirm = ref<boolean>(false);
const selectedTestIds = ref<number[]>([]);
const rejectAllExplicit = ref<boolean>(false);

// Existing reasons that share a word (>= 4 characters) with the free text being
// typed, ranked by number of matching words.
const reasonSuggestions = computed<string[]>(() => {
    const words = otherReason.value
        .toLowerCase()
        .split(/\s+/)
        .filter((word) => word.length >= 4);
    if (!words.length) return [];

    const typed = otherReason.value.trim().toLowerCase();
    return statusReasons.value
        .map((reason) => {
            const description = (reason.description || "").toLowerCase();
            const hits = words.filter((word) => description.includes(word)).length;
            return { description: reason.description, hits };
        })
        .filter((reason) => reason.hits > 0 && reason.description.toLowerCase() !== typed)
        .sort((a, b) => b.hits - a.hits)
        .slice(0, 6)
        .map((reason) => reason.description);
});

const applySuggestion = (description: string): void => {
    selectedStatusReason.value = description;
    otherReason.value = "";
};

const fetchOrderDetails = async () => {
    const res = await client.getJson(`/orders/${route.params.identifier}`);
    details.value = res?.data;
};

const handleDialog = (): void => {
    router.back();
};

const cancelReject = async () => {
    const ok = await alertConfirmation("Are you sure you want to cancel?");
    if (ok) handleDialog();
};
const emits = defineEmits(["updated"]);
const showKeyboard = ref<boolean>(false);

const enterInput = (value: "person" | "reason"): void => {
    focusedField.value = value;
    showKeyboard.value = true;
};

const onChange = (input: string): void => {
    if (focusedField.value === "reason") {
        otherReason.value = input;
    } else {
        personTalkedTo.value = input;
    }
};

const onKeyPress = (input: string): void => {
    if (input == "{enter}") {
        showKeyboard.value = false;
    }
};

const getStatusReasons = async (): Promise<void> => {
    const res = await client.getJson("status_reasons");
    statusReasons.value = res?.data;
};

const isset = computed(() => {
    if (!personTalkedTo.value) return false;
    if (selectedStatusReason.value === OTHER_OPTION) return !!otherReason.value.trim();
    return !!selectedStatusReason.value;
});

const canConfirm = computed(
    () => rejectAllExplicit.value || selectedTestIds.value.length > 0
);

const formatStatus = (status: string): string =>
    status ? status.split("-").join(" ") : "";

const toggleTest = (testId: number, event: CustomEvent): void => {
    const checked = (event.detail as { checked: boolean }).checked;
    const index = selectedTestIds.value.indexOf(testId);
    if (checked && index === -1) {
        selectedTestIds.value.push(testId);
    } else if (!checked && index !== -1) {
        selectedTestIds.value.splice(index, 1);
    }
};

const goToConfirm = (): void => {
    if (!isset.value) return;
    showConfirm.value = true;
};

const submitForm = async (): Promise<void> => {
    const tests = details.value?.tests || [];
    const isAll =
        rejectAllExplicit.value ||
        (tests.length > 0 && selectedTestIds.value.length === tests.length);

    const isOther = selectedStatusReason.value === OTHER_OPTION;
    const otherText = otherReason.value.trim();

    // Resolve to an existing reason id where possible.
    let reasonId: number | null = null;
    const lookup = isOther ? otherText.toLowerCase() : selectedStatusReason.value;
    for (const status of statusReasons.value) {
        const description = isOther
            ? (status.description || "").trim().toLowerCase()
            : status.description;
        if (description === lookup) {
            reasonId = status.id;
            break;
        }
    }

    const body: Record<string, unknown> = {
        order_id: details.value?.order_id,
        person_talked_to: personTalkedTo.value,
    };
    if (isOther && reasonId === null) {
        body.other_reason = otherText;
    } else {
        body.status_reason_id = reasonId;
    }
    if (isAll) {
        body.reject_all = true;
    } else {
        body.test_ids = selectedTestIds.value;
    }

    const res = await client.putJson("order_statuses/rejected", body);
    if (res?.data) {
        toastSuccess(
            isAll
                ? "Specimen and all tests rejected successfully"
                : "Selected test(s) rejected successfully"
        );
        router.push("/tests");
        emits("updated", true);
    }
};

onMounted(() => {
    fetchOrderDetails();
    getStatusReasons();
});
</script>

<style scoped>
.keyboard {
    width: 100%;
    bottom: 0;
    position: absolute !important;
    font-size: 30px;
    text-transform: uppercase;
    font-weight: 400;
}
</style>
